#!/bin/bash
# CrowdStrike Falcon - Operator Install Script
# Generated by CrowdStrike Sensor Install Wizard
#
# Usage:
#   ./install.sh [--verbose|-v] [--auto|-a] [--kubeconfig PATH]
#
#   --verbose / -v        Print every command as it runs (set -x equivalent)
#   --auto    / -a        Skip confirmation prompts and proceed automatically
#   --kubeconfig PATH     Path to kubeconfig file (defaults to kubectl default)
#
# Required environment variables (set before running or export in your shell):
#   FALCON_CLIENT_ID       Your CrowdStrike API client ID
#   FALCON_CLIENT_SECRET   Your CrowdStrike API client secret (prompted if not set)
#
# Optional environment variables:
#   CLUSTER_NAME                Expected cluster name (enforces kube context verification)
#   FALCON_PROVISIONING_TOKEN   Falcon provisioning token (included in sensor/kac secret if set)
#
# For private registry (when using a private registry URL):
#   PRIVATE_REGISTRY_USERNAME  Username for pushing to private registry
#   PRIVATE_REGISTRY_PASSWORD  Password/token for pushing to private registry
#
set -euo pipefail
# ---------------------------------------------------------------------------
# Configuration
# ---------------------------------------------------------------------------
FALCON_CLIENT_ID="b4d8380dd88c49cb9b5c847337f16810"
FALCON_CID="3CA49F4E80AC4C19AF9FC8AF240FAF83-78"
OPERATOR_VERSION="1.14.0"
CONFIG_FILE="falcon-deployment.yaml"

# ---------------------------------------------------------------------------
# Parse flags
# ---------------------------------------------------------------------------
VERBOSE=false
AUTO=false
KUBECONFIG_PATH=""
while [ $# -gt 0 ]; do
  case "$1" in
    --verbose|-v) VERBOSE=true; shift ;;
    --auto|-a)    AUTO=true; shift ;;
    --kubeconfig)
      [ -z "${2:-}" ] && { echo "--kubeconfig requires a path argument" >&2; exit 1; }
      KUBECONFIG_PATH="$2"; shift 2 ;;
    *) echo "Unknown flag: $1" >&2; exit 1 ;;
  esac
done

kubectl() {
  if [ -n "${KUBECONFIG_PATH}" ]; then
    command kubectl --kubeconfig "${KUBECONFIG_PATH}" "$@"
  else
    command kubectl "$@"
  fi
}

if [ "$VERBOSE" = "true" ]; then
  set -x
fi

# ---------------------------------------------------------------------------
# Prompt for client secret if not already set
# ---------------------------------------------------------------------------
if [ -z "${FALCON_CLIENT_SECRET:-}" ]; then
  { set +x; } 2>/dev/null
  read -r -s -p "Enter FALCON_CLIENT_SECRET: " FALCON_CLIENT_SECRET
  echo
  [ "$VERBOSE" = "true" ] && set -x
fi

# ---------------------------------------------------------------------------
# Helper functions
# ---------------------------------------------------------------------------
step_counter=0
info() {
  step_counter=$((step_counter + 1))
  echo ""
  echo "[Step ${step_counter}] $1"
}

success() {
  echo "  [OK] $1"
}

error() {
  echo "  [ERROR] $1" >&2
  exit 1
}

confirm() {
  if [ "$AUTO" = "true" ]; then
    return 0
  fi
  echo ""
  read -r -p "$1 [y/N] " response
  case "$response" in
    [yY][eE][sS]|[yY]) return 0 ;;
    *) echo "Aborted." >&2; exit 1 ;;
  esac
}

# ---------------------------------------------------------------------------
# Verify kubectl
# ---------------------------------------------------------------------------
info "Verifying kubectl is installed..."
if ! command -v kubectl &>/dev/null; then
  error "kubectl not found. Install it from: https://kubernetes.io/docs/tasks/tools/"
fi
success "kubectl $(kubectl version --client 2>/dev/null | head -1)"

# ---------------------------------------------------------------------------
# Verify kube context matches cluster name
# ---------------------------------------------------------------------------
info "Verifying kube context..."
CURRENT_CONTEXT=$(kubectl config current-context)
if [ -n "${CLUSTER_NAME:-}" ]; then
  if ! echo "${CURRENT_CONTEXT}" | grep -q "${CLUSTER_NAME}"; then
    error "Current kube context '${CURRENT_CONTEXT}' does not match cluster '${CLUSTER_NAME}'. Switch contexts and retry."
  fi
  success "Context '${CURRENT_CONTEXT}' matches cluster '${CLUSTER_NAME}'"
else
  echo "  Cluster context: ${CURRENT_CONTEXT}"
  echo "  (Set CLUSTER_NAME env var to enforce context verification)"
fi

# ---------------------------------------------------------------------------
# Check cluster permissions
# ---------------------------------------------------------------------------
info "Checking cluster permissions..."
MISSING_PERMS=()
kubectl auth can-i get    namespaces                               --all-namespaces &>/dev/null || MISSING_PERMS+=("get namespaces")
kubectl auth can-i create namespaces                               --all-namespaces &>/dev/null || MISSING_PERMS+=("create namespaces")
kubectl auth can-i watch  namespaces                               --all-namespaces &>/dev/null || MISSING_PERMS+=("watch namespaces")
kubectl auth can-i create secrets                                  --all-namespaces &>/dev/null || MISSING_PERMS+=("create secrets")
kubectl auth can-i create serviceaccounts                          --all-namespaces &>/dev/null || MISSING_PERMS+=("create serviceaccounts")
kubectl auth can-i create clusterroles                             --all-namespaces &>/dev/null || MISSING_PERMS+=("create clusterroles")
kubectl auth can-i create clusterrolebindings                      --all-namespaces &>/dev/null || MISSING_PERMS+=("create clusterrolebindings")
kubectl auth can-i create customresourcedefinitions                --all-namespaces &>/dev/null || MISSING_PERMS+=("create customresourcedefinitions")
kubectl auth can-i create falcondeployments.falcon.crowdstrike.com --all-namespaces &>/dev/null || MISSING_PERMS+=("create falcondeployments")
kubectl auth can-i get    falcondeployments.falcon.crowdstrike.com --all-namespaces &>/dev/null || MISSING_PERMS+=("get falcondeployments")
kubectl auth can-i watch  falcondeployments.falcon.crowdstrike.com --all-namespaces &>/dev/null || MISSING_PERMS+=("watch falcondeployments")

if [ ${#MISSING_PERMS[@]} -gt 0 ]; then
  error "Missing cluster permissions: ${MISSING_PERMS[*]}. Grant these roles and retry."
fi
success "All required permissions present"

# ---------------------------------------------------------------------------
# Download CrowdStrike pull script
# ---------------------------------------------------------------------------
info "Downloading CrowdStrike pull script..."
FALCON_TMPDIR=$(mktemp -d)
trap 'rm -rf "${FALCON_TMPDIR}"' EXIT
FALCON_PULL_SCRIPT="${FALCON_TMPDIR}/falcon-container-sensor-pull.sh"
# Pull script version is pinned independently of the operator/chart version.
# The pull script (github.com/CrowdStrike/falcon-scripts) and the operator/chart
# follow separate release cycles. Update this version when falcon-scripts ships
# a new release that improves compatibility with the current operator version.
curl -sSL "https://github.com/CrowdStrike/falcon-scripts/releases/download/v1.13.0/falcon-container-sensor-pull.sh" \
  -o "${FALCON_PULL_SCRIPT}"
_pull_script_digest=$(sha256sum "${FALCON_PULL_SCRIPT}" | awk '{print "sha256:"$1}')
if [ "${_pull_script_digest}" != "sha256:6c9aed5b2466261667d61ee54fd55e9a4a93ce9fefa3adf66e721a5de52fa582" ]; then
  echo "" >&2
  echo "  [ERROR] Pull script digest mismatch:" >&2
  echo "    expected: sha256:6c9aed5b2466261667d61ee54fd55e9a4a93ce9fefa3adf66e721a5de52fa582" >&2
  echo "    got:      ${_pull_script_digest}" >&2
  echo "" >&2
  echo "  The downloaded falcon-container-sensor-pull.sh does not match the expected digest." >&2
  echo "  Regenerate the install bundle from the Falcon console to get the latest expected version," >&2
  echo "  then re-run this script." >&2
  echo "" >&2
  echo "  If you observe unexpected digest values that persist after regenerating your install bundle," >&2
  echo "  contact CrowdStrike Support at https://supportportal.crowdstrike.com" >&2
  exit 1
fi
chmod +x "${FALCON_PULL_SCRIPT}"
success "Pull script downloaded and verified"

# ---------------------------------------------------------------------------
# Verify sensor image access
# ---------------------------------------------------------------------------
info "Verifying sensor image access..."

verify_image_access() {
  local sensor_type="$1"
  { set +x; } 2>/dev/null
  if ! "${FALCON_PULL_SCRIPT}" \
      --client-id "${FALCON_CLIENT_ID}" \
      --client-secret "${FALCON_CLIENT_SECRET}" \
      --type "${sensor_type}" --list-tags &>/dev/null; then
    error "Cannot access ${sensor_type} images. Ensure your API credentials have the following scopes: Falcon Container CLI (write), Falcon Container Image (read/write), Falcon Images Download (read), Sensor Download (read)."
  fi
  [ "$VERBOSE" = "true" ] && set -x
  success "${sensor_type} image access verified"
}

verify_image_access "falcon-sensor"
verify_image_access "falcon-kac"
verify_image_access "falcon-imageanalyzer"

# ---------------------------------------------------------------------------
# Get registry pull token
# ---------------------------------------------------------------------------
info "Retrieving CrowdStrike registry pull token..."
{ set +x; } 2>/dev/null
CREDENTIALS=$("${FALCON_PULL_SCRIPT}" \
  --client-id "${FALCON_CLIENT_ID}" \
  --client-secret "${FALCON_CLIENT_SECRET}" \
  --dump-credentials)

CS_REGISTRY_USERNAME=$(echo "${CREDENTIALS}" | awk '/CS Registry Username:/ {print $NF}')
CS_REGISTRY_PASSWORD=$(echo "${CREDENTIALS}" | awk '/CS Registry Password:/ {print $NF}')
success "CrowdStrike pull token retrieved"
[ "$VERBOSE" = "true" ] && set -x

# ---------------------------------------------------------------------------
# Create namespace and FalconSecret
# ---------------------------------------------------------------------------
info "Creating namespace and FalconSecret..."
if kubectl get namespace "falcon-system" &>/dev/null; then
  success "Namespace 'falcon-system' already exists"
else
  kubectl create namespace "falcon-system"
  success "Namespace 'falcon-system' created"
fi

kubectl wait --for=jsonpath='{.status.phase}'=Active "namespace/falcon-system" --timeout=120s &>/dev/null \
  || error "Namespace 'falcon-system' did not become active within 120s"

# SECURITY NOTE: --from-literal passes the secret as a CLI argument, making it
# briefly visible in /proc/PID/cmdline on Linux. On shared hosts, consider using
# a file-based approach (--from-file) or a secrets manager integration instead.
{ set +x; } 2>/dev/null
FALCON_SECRET_ARGS=(
  --from-literal=falcon-client-id="${FALCON_CLIENT_ID}"
  --from-literal=falcon-client-secret="${FALCON_CLIENT_SECRET}"
  --from-literal=falcon-cid="${FALCON_CID}"
)
if [ -n "${FALCON_PROVISIONING_TOKEN:-}" ]; then
  FALCON_SECRET_ARGS+=(--from-literal=falcon-provisioning-token="${FALCON_PROVISIONING_TOKEN}")
fi
kubectl create secret generic "falcon-secrets" \
  --namespace "falcon-system" \
  "${FALCON_SECRET_ARGS[@]}" \
  --dry-run=client -o yaml | kubectl apply -f -
[ "$VERBOSE" = "true" ] && set -x
success "FalconSecret 'falcon-secrets' applied in namespace 'falcon-system'"

# ---------------------------------------------------------------------------
# Verify operator version
# ---------------------------------------------------------------------------
info "Verifying operator version..."
if [ -z "${OPERATOR_VERSION}" ]; then
  error "OPERATOR_VERSION is not set — cannot pin operator version. Regenerate the install bundle."
fi
success "Operator version: ${OPERATOR_VERSION}"

# ---------------------------------------------------------------------------
# Install Falcon Operator
# For air-gapped clusters, download falcon-operator.yaml manually and apply
# from a local path. HTTPS is the only integrity verification for this fetch.
# ---------------------------------------------------------------------------
info "Installing Falcon Operator v${OPERATOR_VERSION}..."
kubectl apply -f "https://github.com/CrowdStrike/falcon-operator/releases/download/v${OPERATOR_VERSION}/falcon-operator.yaml"
success "Falcon Operator manifest applied"

# ---------------------------------------------------------------------------
# Wait for operator ready
# ---------------------------------------------------------------------------
info "Waiting for Falcon Operator to be ready..."
kubectl wait --for=condition=available \
  deployment/falcon-operator-controller-manager \
  -n falcon-operator \
  --timeout=120s \
  || error "Falcon Operator did not become available within 120s. Check: kubectl get pods -n falcon-operator"
success "Falcon Operator is running"

# ---------------------------------------------------------------------------
# Verify config file is present
# ---------------------------------------------------------------------------
info "Verifying FalconDeployment config file..."
if [ ! -f "${CONFIG_FILE}" ]; then
  error "Config file '${CONFIG_FILE}' not found. Run this script from the directory containing the downloaded bundle."
fi
success "Config file '${CONFIG_FILE}' found"

# ---------------------------------------------------------------------------
# Dry-run CR apply
# ---------------------------------------------------------------------------
info "Validating FalconDeployment CR (server dry-run)..."
if ! kubectl apply -f "${CONFIG_FILE}" --dry-run=server &>/dev/null; then
  error "FalconDeployment dry-run failed. Check config file, cluster permissions, and CRD availability."
fi
success "Dry-run passed"

# ---------------------------------------------------------------------------
# Apply FalconDeployment and verify
# ---------------------------------------------------------------------------
info "Applying FalconDeployment CR..."
confirm "Proceed with kubectl apply? This will deploy CrowdStrike sensors to cluster '${CURRENT_CONTEXT}'."

kubectl apply -f "${CONFIG_FILE}"
success "FalconDeployment applied"

info "Waiting for deployment to reconcile..."
kubectl wait falcondeployment/falcon-deployment \
  --for=condition=Success \
  --timeout=180s \
  2>/dev/null \
  || echo "  [WARN] FalconDeployment did not complete installation within 3m — check operator logs with: kubectl logs -n falcon-operator -l app=falcon-operator"

echo ""
echo "--- FalconDeployment status ---"
kubectl get falcondeployment -A
echo ""
echo "✓ Falcon Operator is ready!"

wait_for_rollout() {
  local kind="$1" name="$2" ns="$3"
  local deadline=$(( $(date +%s) + 120 ))

  echo "Waiting for ${kind}/${name} to appear in ${ns}..."
  until kubectl get "${kind}/${name}" -n "${ns}" &>/dev/null; do
    if (( $(date +%s) >= deadline )); then
      echo "  [WARN] ${kind}/${name} never appeared in ${ns}"
      echo "         Check operator logs: kubectl logs -n ${OPERATOR_NAMESPACE:-falcon-operator} -l control-plane=controller-manager --tail=50"
      echo ""
      return 0
    fi
    sleep 5
  done

  if kubectl rollout status "${kind}/${name}" -n "${ns}" --timeout=180s; then
    echo "✓ ${kind}/${name} is ready!"
  else
    echo "  [WARN] ${kind}/${name} did not become ready within 180s "
  fi

  echo ""
  kubectl get ${kind},pods -n "${ns}" || true
  echo ""
}

wait_for_rollout daemonset falcon-node-sensor falcon-system

wait_for_rollout deployment falcon-kac falcon-kac

wait_for_rollout deployment falcon-image-analyzer falcon-image-analyzer

success "CrowdStrike Falcon deployment complete!"
echo ""
echo ""
echo "To uninstall, run these steps in order:"
_STEP=1
_cleanup_step() { echo "  ${_STEP}. $1"; _STEP=$((_STEP + 1)); }

_cleanup_step "kubectl delete falcondeployment --all"
_cleanup_step "kubectl delete -f https://github.com/CrowdStrike/falcon-operator/releases/download/v${OPERATOR_VERSION}/falcon-operator.yaml"

_cleanup_step "kubectl delete namespace falcon-system --ignore-not-found"
_cleanup_step "kubectl delete namespace falcon-kac --ignore-not-found"
_cleanup_step "kubectl delete namespace falcon-image-analyzer --ignore-not-found"

_cleanup_step "kubectl delete secret falcon-secrets -n falcon-system --ignore-not-found"
_cleanup_step "kubectl delete namespace falcon-system --ignore-not-found"
